INSERT INTO `sys_notice` (`id`,`title`,`content`,`publish_time`,`notice_type`,`publisher_id`,`status`) VALUES
(1,'关于11月考季延长开放时间的通知','为配合考研冲刺复习，自2026年11月3日起，图书馆三层、五层自习室开放时间延长至23:00，末班时段调整为19:00-23:00。','2026-11-01 09:40:00','系统公告',2,'已发布'),
(2,'图书馆五层考研专室座位调整说明','五层专室新增12个独立隔板位，11月1日起开放预约。','2026-10-28 09:40:00','座位调整',2,'已发布'),
(3,'自习室违约规则修订（v3）','签到窗口调整为开始前后15分钟，未签到扣3分。','2026-10-15 09:40:00','规则修订',2,'已发布'),
(4,'第一教学楼105电路检修暂停开放','105室因电路检修暂停开放，恢复时间另行通知。','2026-11-01 08:40:00','停用通知',4,'草稿'),
(5,'考研冲刺期座位预约提醒','冲刺期请提前预约，避免占座不来。','2026-10-20 09:40:00','预约提醒',2,'已发布');
