-- NEW-059 考研自习室座位预约与学习打卡系统 初始化脚本
-- 执行：mysql -uroot -p123456 < sql/init.sql
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS `new_059`;
CREATE DATABASE `new_059` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_059`;
SET FOREIGN_KEY_CHECKS=0;

-- ===== NEW-059 业务表（8 张）与创新点表（3 张） =====

CREATE TABLE `study_room` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `room_no` varchar(20) NOT NULL COMMENT '自习室编号 ZX+2位楼栋+2位序号',
  `room_name` varchar(50) NOT NULL COMMENT '名称',
  `building_name` varchar(50) NOT NULL COMMENT '所在楼栋',
  `floor_no` int NOT NULL DEFAULT 1 COMMENT '楼层 1-20',
  `seat_count` int NOT NULL DEFAULT 0 COMMENT '座位总数（由座位档案汇总）',
  `open_start` time NOT NULL DEFAULT '07:30:00' COMMENT '开放开始时间',
  `open_end` time NOT NULL DEFAULT '22:30:00' COMMENT '开放结束时间',
  `slot_minutes` int NOT NULL DEFAULT 240 COMMENT '时段长度 120/180/240',
  `quiet_level` varchar(10) NOT NULL DEFAULT '安静' COMMENT '安静/较安静/可讨论',
  `manager_id` bigint NOT NULL COMMENT '负责管理员 sys_user.id',
  `status` varchar(20) NOT NULL DEFAULT '开放' COMMENT '开放/满员/维护中/已关闭',
  `cover_image` varchar(255) DEFAULT NULL COMMENT '封面图相对路径 /uploads/seed/room/NN.jpg',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_no` (`room_no`),
  KEY `idx_building_status` (`building_name`,`status`),
  KEY `idx_manager` (`manager_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='自习室';

CREATE TABLE `seat` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `seat_no` varchar(24) NOT NULL COMMENT '座位编号 自习室编号+区域字母+2位序号',
  `room_id` bigint NOT NULL COMMENT '自习室',
  `zone_name` varchar(20) NOT NULL COMMENT '区域 如A区靠窗',
  `row_no` int NOT NULL DEFAULT 1 COMMENT '行号 1-30',
  `col_no` int NOT NULL DEFAULT 1 COMMENT '列号 1-20',
  `seat_type` varchar(20) NOT NULL DEFAULT '普通' COMMENT '普通/靠窗/带电源/独立隔板',
  `has_power` tinyint NOT NULL DEFAULT 0 COMMENT '是否有电源',
  `has_lamp` tinyint NOT NULL DEFAULT 0 COMMENT '是否有台灯',
  `status` varchar(20) NOT NULL DEFAULT '可用' COMMENT '可用/使用中/已预约/维修/停用',
  `stop_reason` varchar(200) DEFAULT NULL COMMENT '停用原因',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_seat_no` (`seat_no`),
  KEY `idx_room_zone` (`room_id`,`zone_name`),
  KEY `idx_room_status` (`room_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='座位';

CREATE TABLE `seat_booking` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_no` varchar(32) NOT NULL COMMENT '预约编号 YY+yyMMdd+5位序号',
  `seat_id` bigint NOT NULL COMMENT '座位',
  `room_id` bigint NOT NULL COMMENT '自习室（冗余）',
  `student_id` bigint NOT NULL COMMENT '学生 sys_user.id',
  `booking_date` date NOT NULL COMMENT '预约日期',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `status` varchar(20) NOT NULL DEFAULT '待生效' COMMENT '待生效/待签到/学习中/已完成/已违约/已取消',
  `checkin_time` datetime DEFAULT NULL COMMENT '签到时间',
  `checkout_time` datetime DEFAULT NULL COMMENT '签退时间',
  `cancel_reason` varchar(200) DEFAULT NULL COMMENT '取消原因',
  `booking_code` varchar(8) DEFAULT NULL COMMENT '预约码（后4位用于签到）',
  `lock_expire_time` datetime DEFAULT NULL COMMENT '座位锁定到期时间',
  `risk_level` varchar(10) DEFAULT NULL COMMENT '预约时的风险等级快照',
  `source` varchar(20) NOT NULL DEFAULT '学生预约' COMMENT '学生预约/候补递补/管理员代订',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_booking_no` (`booking_no`),
  KEY `idx_seat_date` (`seat_id`,`booking_date`,`start_time`),
  KEY `idx_student_date` (`student_id`,`booking_date`),
  KEY `idx_status_date` (`status`,`booking_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='座位预约';

CREATE TABLE `checkin_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` bigint NOT NULL COMMENT '预约',
  `student_id` bigint NOT NULL COMMENT '学生',
  `action_type` varchar(20) NOT NULL COMMENT '签到/签退/临时离座/返回/管理员清座',
  `action_time` datetime NOT NULL COMMENT '动作时间',
  `seat_no` varchar(24) NOT NULL COMMENT '座位编号',
  `verify_code` varchar(10) DEFAULT NULL COMMENT '核销码',
  `operator_type` varchar(20) NOT NULL DEFAULT '本人' COMMENT '本人/管理员代操作/系统任务',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  KEY `idx_booking_action` (`booking_id`,`action_type`),
  KEY `idx_student_time` (`student_id`,`action_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='签到记录';

CREATE TABLE `study_duration` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `total_minutes` int NOT NULL DEFAULT 0 COMMENT '在场总分钟',
  `valid_minutes` int NOT NULL DEFAULT 0 COMMENT '有效分钟',
  `session_count` int NOT NULL DEFAULT 0 COMMENT '场次',
  `first_in_time` datetime DEFAULT NULL COMMENT '最早签到',
  `last_out_time` datetime DEFAULT NULL COMMENT '最晚签退',
  `break_minutes` int NOT NULL DEFAULT 0 COMMENT '离座分钟',
  `calc_status` varchar(20) NOT NULL DEFAULT '已结算' COMMENT '待结算/已结算/已修正',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_date` (`student_id`,`stat_date`),
  KEY `idx_date_minutes` (`stat_date`,`valid_minutes`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习时长日汇总';

CREATE TABLE `violation_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `record_no` varchar(32) NOT NULL COMMENT '违约编号 WY+yyMMdd+4位序号',
  `student_id` bigint NOT NULL COMMENT '学生',
  `booking_id` bigint NOT NULL COMMENT '预约',
  `violation_type` varchar(20) NOT NULL COMMENT '未签到/迟到超15分钟/提前离座/未签退/占座不来',
  `occur_time` datetime NOT NULL COMMENT '发生时间',
  `deduct_score` int NOT NULL DEFAULT 1 COMMENT '扣分 1-5',
  `handle_status` varchar(20) NOT NULL DEFAULT '待处理' COMMENT '待处理/已确认/申诉中/已撤销',
  `appeal_reason` varchar(300) DEFAULT NULL COMMENT '申诉理由',
  `appeal_time` datetime DEFAULT NULL COMMENT '申诉时间',
  `handle_result` varchar(300) DEFAULT NULL COMMENT '处理结果',
  `handler_id` bigint DEFAULT NULL COMMENT '处理人',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_no` (`record_no`),
  KEY `idx_student_time` (`student_id`,`occur_time`),
  KEY `idx_handle_status` (`handle_status`,`occur_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='违约记录';

CREATE TABLE `demand_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `room_id` bigint NOT NULL COMMENT '自习室',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `hour_slot` varchar(20) NOT NULL COMMENT '时段 如08:00-12:00',
  `seat_total` int NOT NULL DEFAULT 0 COMMENT '座位总数',
  `booked_count` int NOT NULL DEFAULT 0 COMMENT '预约数',
  `arrived_count` int NOT NULL DEFAULT 0 COMMENT '到达数',
  `occupancy_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '占用率',
  `arrive_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '到达率',
  `demand_index` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '热力指数',
  `calc_time` datetime NOT NULL COMMENT '计算时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_date_slot` (`room_id`,`stat_date`,`hour_slot`),
  KEY `idx_date_index` (`stat_date`,`demand_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='需求热力快照';

CREATE TABLE `blacklist_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生',
  `reason_type` varchar(30) NOT NULL COMMENT '违约3次/违约5次/占座不来/管理员人工加入',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `release_type` varchar(20) NOT NULL DEFAULT '自动解除' COMMENT '自动解除/人工解除/学工减免',
  `violation_nos` varchar(500) DEFAULT NULL COMMENT '关联违约单号，逗号分隔',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人',
  `release_remark` varchar(300) DEFAULT NULL COMMENT '减免说明',
  `status` varchar(20) NOT NULL DEFAULT '生效中' COMMENT '生效中/已解除/已过期',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  KEY `idx_student_status` (`student_id`,`status`),
  KEY `idx_end_date` (`end_date`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='黑名单记录';

-- ===== 创新点：规则配置 / 计算快照 / 人工修正 =====

CREATE TABLE `risk_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_no` varchar(32) NOT NULL COMMENT '规则编号',
  `rule_version` varchar(20) NOT NULL COMMENT '版本号 v1/v2/v3',
  `w_violation` int NOT NULL DEFAULT 30 COMMENT '近30天违约次数权重',
  `w_arrive` int NOT NULL DEFAULT 25 COMMENT '预约到座率权重',
  `w_advance` int NOT NULL DEFAULT 15 COMMENT '平均提前预约时长权重',
  `w_occupy` int NOT NULL DEFAULT 15 COMMENT '同时段座位占用率权重',
  `w_season` int NOT NULL DEFAULT 15 COMMENT '时段与考季系数权重',
  `total_weight` int NOT NULL DEFAULT 100 COMMENT '权重合计，必须等于100',
  `effect_time` datetime NOT NULL COMMENT '生效时间',
  `status` varchar(20) NOT NULL DEFAULT '生效中' COMMENT '生效中/已归档',
  `remark` varchar(200) DEFAULT NULL COMMENT '调整说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_no` (`rule_no`),
  KEY `idx_status_effect` (`status`,`effect_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险规则配置';

CREATE TABLE `risk_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_no` varchar(32) NOT NULL COMMENT '快照编号',
  `student_id` bigint NOT NULL COMMENT '学生',
  `rule_id` bigint NOT NULL COMMENT '规则ID',
  `rule_version` varchar(20) NOT NULL COMMENT '规则版本（留痕）',
  `total_score` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '加权总分',
  `risk_level` varchar(10) NOT NULL COMMENT '低风险/中风险/较高风险/高风险',
  `factor_json` text COMMENT '输入快照与各因素得分 JSON',
  `conclusion` varchar(300) DEFAULT NULL COMMENT '结论',
  `unmet` varchar(300) DEFAULT NULL COMMENT '未满足条件',
  `improve` varchar(300) DEFAULT NULL COMMENT '可改进项',
  `suggest_slot` varchar(60) DEFAULT NULL COMMENT '推荐时段',
  `calc_time` datetime NOT NULL COMMENT '计算时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_snapshot_no` (`snapshot_no`),
  KEY `idx_student_time` (`student_id`,`calc_time`),
  KEY `idx_level` (`risk_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险计算快照';

CREATE TABLE `risk_correction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_id` bigint NOT NULL COMMENT '快照ID',
  `student_id` bigint NOT NULL COMMENT '学生',
  `origin_score` decimal(5,2) NOT NULL COMMENT '原始分数',
  `origin_level` varchar(10) NOT NULL COMMENT '原始等级',
  `new_score` decimal(5,2) NOT NULL COMMENT '修正后分数',
  `new_level` varchar(10) NOT NULL COMMENT '修正后等级',
  `correct_reason` varchar(300) NOT NULL COMMENT '修正原因（不少于5字）',
  `operator_id` bigint NOT NULL COMMENT '操作人',
  `correct_time` datetime NOT NULL COMMENT '修正时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  KEY `idx_snapshot` (`snapshot_id`),
  KEY `idx_student` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险人工修正留痕';

CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(50) NOT NULL COMMENT '登录账号',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 密码',
  `real_name` varchar(50) NOT NULL COMMENT '真实姓名',
  `user_no` varchar(32) DEFAULT NULL COMMENT '学号/工号',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `email` varchar(80) DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像相对路径',
  `gender` varchar(10) DEFAULT NULL COMMENT '男/女',
  `dept_id` bigint DEFAULT NULL COMMENT '所属院系ID',
  `dept_name` varchar(60) DEFAULT NULL COMMENT '所属院系',
  `title` varchar(40) DEFAULT NULL COMMENT '职称/年级',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `credit_score` int NOT NULL DEFAULT 100 COMMENT '诚信分',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近登录时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_user_no` (`user_no`),
  KEY `idx_dept` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';

CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_name` varchar(50) NOT NULL COMMENT '角色名称',
  `role_code` varchar(50) NOT NULL COMMENT '角色编码 ROLE_XXX',
  `data_scope` varchar(20) NOT NULL DEFAULT '本人' COMMENT '本人/本部门/全部',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户',
  `role_id` bigint NOT NULL COMMENT '角色',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_role` (`user_id`, `role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户角色';

CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '上级菜单，0为根',
  `menu_name` varchar(50) NOT NULL COMMENT '菜单名称',
  `path` varchar(100) DEFAULT NULL COMMENT '路由地址',
  `component` varchar(150) DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(100) DEFAULT NULL COMMENT '权限标识',
  `menu_type` varchar(20) NOT NULL DEFAULT '菜单' COMMENT '目录/菜单/按钮',
  `icon` varchar(40) DEFAULT NULL COMMENT '图标名',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序',
  `visible` tinyint NOT NULL DEFAULT 1 COMMENT '1显示 0隐藏',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='菜单权限';

CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id` bigint NOT NULL COMMENT '角色',
  `menu_id` bigint NOT NULL COMMENT '菜单',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_menu` (`role_id`, `menu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色菜单';

CREATE TABLE `sys_dict_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_name` varchar(60) NOT NULL COMMENT '字典名称',
  `dict_type` varchar(60) NOT NULL COMMENT '字典编码',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='字典类型';

CREATE TABLE `sys_dict_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` varchar(60) NOT NULL COMMENT '字典编码',
  `dict_label` varchar(60) NOT NULL COMMENT '显示标签',
  `dict_value` varchar(60) NOT NULL COMMENT '字典值',
  `tag_type` varchar(20) DEFAULT NULL COMMENT '标签样式',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='字典数据';

CREATE TABLE `sys_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `file_name` varchar(150) NOT NULL COMMENT '原文件名',
  `file_path` varchar(255) NOT NULL COMMENT '相对路径 /uploads/...',
  `file_size` bigint NOT NULL DEFAULT 0 COMMENT '字节',
  `file_type` varchar(40) DEFAULT NULL COMMENT '扩展名',
  `biz_type` varchar(40) DEFAULT NULL COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID',
  `uploader_id` bigint DEFAULT NULL COMMENT '上传人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_biz` (`biz_type`, `biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='上传文件';

CREATE TABLE `sys_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(150) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '正文',
  `notice_type` varchar(20) NOT NULL DEFAULT '通知' COMMENT '通知/公告/考试提醒',
  `publish_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `publisher_id` bigint DEFAULT NULL COMMENT '发布人',
  `status` varchar(20) NOT NULL DEFAULT '已发布' COMMENT '草稿/已发布/已下线',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公告';

CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receiver_id` bigint NOT NULL COMMENT '接收人',
  `title` varchar(150) NOT NULL COMMENT '标题',
  `content` varchar(500) NOT NULL COMMENT '内容',
  `msg_type` varchar(30) NOT NULL DEFAULT '系统通知' COMMENT '审核/批阅/成绩/预警/系统通知',
  `biz_type` varchar(40) DEFAULT NULL COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID',
  `read_flag` tinyint NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_receiver_read` (`receiver_id`, `read_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站内消息';

CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `module` varchar(40) NOT NULL COMMENT '模块',
  `oper_type` varchar(30) NOT NULL COMMENT '操作类型',
  `biz_no` varchar(50) DEFAULT NULL COMMENT '业务编号',
  `content` varchar(500) DEFAULT NULL COMMENT '操作内容',
  `oper_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `oper_name` varchar(50) DEFAULT NULL COMMENT '操作人',
  `oper_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `ip` varchar(64) DEFAULT NULL COMMENT 'IP',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_oper_time` (`oper_time`),
  KEY `idx_biz_no` (`biz_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';





















SET FOREIGN_KEY_CHECKS=1;
